"use client"

import { AgentChatActions } from "@/components/boardui/application/agent-chat/agent-chat-actions"
import {
  AgentChatHistory,
  type ChatThreadSummary,
} from "@/components/boardui/application/agent-chat/agent-chat-history"
import { AgentMessage } from "@/components/boardui/application/agent-chat/agent-chat-message"
import { AgentComposer } from "@/components/boardui/application/agent-chat/agent-composer"
import { DemoTransport } from "@/components/boardui/application/agent-chat/demo-transport"
import { AgentThinking } from "@/components/boardui/application/agent-thinking/agent-thinking"
import { cx } from "@/components/boardui/utils/cx"
import { useChat } from "@ai-sdk/react"
import { RiHistoryLine } from "@remixicon/react"
import type { UIMessage } from "ai"
import { useCallback, useEffect, useMemo, useRef, useState } from "react"

const STORAGE_KEY = "agents-kit:boardui-chat-threads"
const MAX_THREADS = 30
const SUGGESTIONS = [
  "Explain what this starter does",
  "Write a product update in three sentences",
  "Give me five names for a scheduling app",
]

interface StoredThread extends ChatThreadSummary {
  messages: UIMessage[]
  messageAt: Record<string, number>
}

/**
 * BoardUI's free chat starter, adapted for the gallery to use its local demo
 * transport only. It keeps the original transcript, composer, history, share,
 * export, rename, unread, delete, speech and motion behavior without requiring
 * an API route or model key.
 */
export function AgentChat({ className }: { className?: string }) {
  const [input, setInput] = useState("")
  const [threads, setThreads] = useState<StoredThread[]>([])
  const [activeId, setActiveId] = useState("")
  const [activeUpdatedAt, setActiveUpdatedAt] = useState(0)
  const [activeTitle, setActiveTitle] = useState<string | null>(null)
  const [messageAt, setMessageAt] = useState<Record<string, number>>({})
  const [restored, setRestored] = useState(false)
  const [historyOpen, setHistoryOpen] = useState(false)
  const scrollRef = useRef<HTMLDivElement>(null)
  const [transport] = useState(() => new DemoTransport())
  const { messages, sendMessage, setMessages, status, stop, error } = useChat({
    transport,
  })
  const busy = status === "submitted" || status === "streaming"

  useEffect(() => {
    setActiveId(newThreadId())
    setThreads(orderThreads(readThreads()))
    setRestored(true)
  }, [])

  useEffect(() => {
    const unseen = messages.filter(
      (message) => messageAt[message.id] === undefined
    )
    if (unseen.length === 0) return
    const now = Date.now()
    setMessageAt((previous) => ({
      ...previous,
      ...Object.fromEntries(unseen.map((message) => [message.id, now])),
    }))
  }, [messages, messageAt])

  const liveThread = useMemo<StoredThread | null>(
    () =>
      activeId && messages.length > 0
        ? {
            id: activeId,
            title: activeTitle ?? deriveTitle(messages),
            updatedAt: activeUpdatedAt,
            messages,
            messageAt,
          }
        : null,
    [activeId, activeTitle, activeUpdatedAt, messageAt, messages]
  )
  const allThreads = useMemo(
    () =>
      orderThreads(
        liveThread
          ? [liveThread, ...threads.filter((thread) => thread.id !== activeId)]
          : threads
      ),
    [activeId, liveThread, threads]
  )

  useEffect(() => {
    if (!restored || busy) return
    writeThreads(allThreads)
  }, [allThreads, busy, restored])

  useEffect(() => {
    scrollRef.current?.scrollTo({
      top: scrollRef.current.scrollHeight,
      behavior: "smooth",
    })
  }, [busy, messages])

  useEffect(() => {
    if (!historyOpen) return
    const close = (event: KeyboardEvent) => {
      if (event.key === "Escape") setHistoryOpen(false)
    }
    window.addEventListener("keydown", close)
    return () => window.removeEventListener("keydown", close)
  }, [historyOpen])

  const keepLiveThread = useCallback(() => {
    if (!liveThread) return
    setThreads((previous) =>
      orderThreads([
        liveThread,
        ...previous.filter((thread) => thread.id !== liveThread.id),
      ])
    )
  }, [liveThread])

  const submit = (text: string) => {
    const trimmed = text.trim()
    if (!trimmed || busy) return
    setActiveUpdatedAt(Date.now())
    sendMessage({ text: trimmed })
    setInput("")
  }

  const startNewChat = useCallback(() => {
    if (busy) return
    keepLiveThread()
    setActiveId(newThreadId())
    setActiveUpdatedAt(0)
    setActiveTitle(null)
    setMessageAt({})
    setMessages([])
    setInput("")
  }, [busy, keepLiveThread, setMessages])

  const selectThread = useCallback(
    (id: string) => {
      if (busy || id === activeId) return
      const thread = allThreads.find((candidate) => candidate.id === id)
      if (!thread) return
      keepLiveThread()
      setActiveId(id)
      setActiveUpdatedAt(thread.updatedAt)
      setActiveTitle(thread.title)
      setMessageAt(thread.messageAt ?? {})
      setMessages(thread.messages)
      setInput("")
      setHistoryOpen(false)
      if (thread.unread) {
        setThreads((previous) =>
          previous.map((item) =>
            item.id === id ? { ...item, unread: false } : item
          )
        )
      }
    },
    [activeId, allThreads, busy, keepLiveThread, setMessages]
  )

  const renameThread = (id: string, title: string) => {
    if (id === activeId) setActiveTitle(title)
    setThreads((previous) =>
      previous.map((thread) =>
        thread.id === id ? { ...thread, title } : thread
      )
    )
  }
  const toggleUnread = (id: string) =>
    setThreads((previous) =>
      previous.map((thread) =>
        thread.id === id ? { ...thread, unread: !thread.unread } : thread
      )
    )
  const deleteThread = (id: string) => {
    setThreads((previous) => previous.filter((thread) => thread.id !== id))
    if (id !== activeId) return
    setActiveId(newThreadId())
    setActiveUpdatedAt(0)
    setActiveTitle(null)
    setMessageAt({})
    setMessages([])
    setInput("")
  }
  const exportThreads = () => {
    if (allThreads.length === 0) return
    const url = URL.createObjectURL(
      new Blob([JSON.stringify(allThreads, null, 2)], {
        type: "application/json",
      })
    )
    const link = document.createElement("a")
    link.href = url
    link.download = "boardui-chats.json"
    document.body.appendChild(link)
    link.click()
    link.remove()
    setTimeout(() => URL.revokeObjectURL(url), 0)
  }

  const streamedText = messageText(messages.at(-1))
  const transcript = messages
    .map(
      (message) =>
        `${message.role === "user" ? "You" : "Assistant"}: ${messageText(message)}`
    )
    .filter((line) => !line.endsWith(": "))
    .join("\n\n")

  return (
    <div
      className={cx(
        "bg-background-full relative flex h-[620px] min-w-0 gap-3 overflow-hidden rounded-3xl p-3",
        className
      )}
    >
      <div className="bg-background-secondary-default relative flex min-w-0 flex-1 flex-col overflow-hidden rounded-3xl">
        <header className="border-separator-border flex h-12 shrink-0 items-center border-b px-4">
          <span className="text-headline-medium text-text-primary min-w-0 truncate">
            {allThreads.find((thread) => thread.id === activeId)?.title ??
              "New chat"}
          </span>
          {!historyOpen ? (
            <button
              type="button"
              aria-label="Open chat history"
              onClick={() => setHistoryOpen(true)}
              className="text-foreground-icon-secondary hover:bg-background-primary-hover focus-visible:ring-border-focus-ring ml-auto flex size-7 shrink-0 items-center justify-center rounded-md transition-colors focus-visible:ring-2 focus-visible:outline-none xl:hidden"
            >
              <RiHistoryLine className="size-[18px]" aria-hidden />
            </button>
          ) : null}
          <AgentChatActions
            className="ml-0.5 xl:ml-auto"
            transcript={transcript}
            onExport={exportThreads}
            onToggleUnread={() => toggleUnread(activeId)}
            onDelete={() => deleteThread(activeId)}
            disabled={messages.length === 0}
          />
        </header>
        <div ref={scrollRef} className="min-h-0 flex-1 overflow-y-auto">
          <div
            className={cx(
              "mx-auto flex min-h-full w-full max-w-3xl flex-col gap-5 px-4 py-6",
              messages.length === 0 && "justify-center"
            )}
          >
            {messages.length === 0 ? (
              <div className="flex flex-col items-center gap-4 text-center">
                <div>
                  <h2 className="text-title-2-medium text-text-primary">
                    What can I help with?
                  </h2>
                  <p className="text-body-regular text-text-secondary">
                    Local demo answers stream without an API key.
                  </p>
                </div>
                <div className="flex flex-wrap justify-center gap-2">
                  {SUGGESTIONS.map((suggestion) => (
                    <button
                      key={suggestion}
                      type="button"
                      onClick={() => submit(suggestion)}
                      className="bg-background-primary-default text-body-regular text-text-secondary hover:bg-background-primary-hover rounded-full px-3.5 py-2 shadow-xs transition-colors"
                    >
                      {suggestion}
                    </button>
                  ))}
                </div>
              </div>
            ) : (
              messages.map((message, index) => (
                <AgentMessage
                  key={message.id}
                  role={message.role}
                  text={messageText(message)}
                  streaming={busy && index === messages.length - 1}
                  at={messageAt[message.id]}
                />
              ))
            )}
            {busy && streamedText.length === 0 ? (
              <AgentThinking variant="wave" label="Thinking" className="px-1" />
            ) : null}
            {error ? (
              <p
                role="alert"
                className="text-body-regular text-text-tertiary px-1"
              >
                The local demo was interrupted. Try again.
              </p>
            ) : null}
          </div>
        </div>
        <div className="shrink-0 px-3 pb-3">
          <div className="mx-auto w-full max-w-3xl">
            <AgentComposer
              value={input}
              onValueChange={setInput}
              onSubmit={() => submit(input)}
              onStop={stop}
              busy={busy}
              provider="Demo mode"
              messageCount={messages.length}
            />
          </div>
        </div>
      </div>
      {historyOpen ? (
        <button
          type="button"
          aria-label="Close chat history"
          onClick={() => setHistoryOpen(false)}
          className="focus-visible:ring-border-focus-ring absolute inset-y-0 right-[272px] left-0 z-20 bg-black/30 focus-visible:ring-2 focus-visible:outline-none xl:hidden"
        />
      ) : null}
      <AgentChatHistory
        threads={allThreads}
        activeId={activeId}
        onSelect={selectThread}
        onNewChat={startNewChat}
        onRename={renameThread}
        onToggleUnread={toggleUnread}
        onDelete={deleteThread}
        onExport={exportThreads}
        disabled={busy}
        className={cx(
          "z-30 xl:static xl:flex",
          historyOpen
            ? "absolute inset-y-3 right-3 flex max-w-[calc(100%-1.5rem)] shadow-lg"
            : "hidden"
        )}
      />
    </div>
  )
}

function messageText(message?: UIMessage) {
  return (
    message?.parts
      .filter((part) => part.type === "text")
      .map((part) => part.text)
      .join("") ?? ""
  )
}

function deriveTitle(messages: UIMessage[]) {
  const first = messages.find((message) => message.role === "user")
  const text = messageText(first).trim()
  return text.length > 42
    ? `${text.slice(0, 39).trimEnd()}…`
    : text || "New chat"
}

function newThreadId() {
  return globalThis.crypto?.randomUUID?.() ?? `chat-${Date.now()}`
}

function orderThreads(threads: StoredThread[]) {
  return [...threads]
    .sort((a, b) => b.updatedAt - a.updatedAt)
    .slice(0, MAX_THREADS)
}

function readThreads(): StoredThread[] {
  try {
    const parsed: unknown = JSON.parse(
      window.localStorage.getItem(STORAGE_KEY) ?? "[]"
    )
    return Array.isArray(parsed) ? parsed.filter(isStoredThread) : []
  } catch {
    return []
  }
}

function writeThreads(threads: StoredThread[]) {
  try {
    window.localStorage.setItem(STORAGE_KEY, JSON.stringify(threads))
  } catch {
    // Storage may be disabled; the live thread still works.
  }
}

function isStoredThread(value: unknown): value is StoredThread {
  if (!value || typeof value !== "object") return false
  const thread = value as Partial<StoredThread>
  return (
    typeof thread.id === "string" &&
    typeof thread.title === "string" &&
    typeof thread.updatedAt === "number" &&
    Array.isArray(thread.messages)
  )
}

"use client";

import { RiCheckLine, RiMoreFill, RiUploadLine } from "@remixicon/react";
import { useEffect, useState } from "react";

import {
  Dropdown,
  DropdownGroup,
  DropdownItem,
  DropdownPopover,
  DropdownTrigger,
} from "@/components/boardui/base/dropdown/dropdown";
import { cx } from "@/components/boardui/utils/cx";

/**
 * The controls in the top right of the chat surface: share the open chat, and
 * a menu of the actions that apply to it.
 *
 * Every entry does something the starter can actually do — copy, download,
 * mark, delete. Nothing here is a placeholder waiting on a backend, because a
 * control that looks live and does nothing is worse than no control.
 */

export interface AgentChatActionsProps {
  /** Plain-text transcript of the open chat, for share and copy. */
  transcript: string;
  onExport: () => void;
  onToggleUnread: () => void;
  onDelete: () => void;
  /** No chat open yet, so there is nothing to act on. */
  disabled?: boolean;
  className?: string;
}

export function AgentChatActions({
  transcript,
  onExport,
  onToggleUnread,
  onDelete,
  disabled = false,
  className,
}: AgentChatActionsProps) {
  const [menuOpen, setMenuOpen] = useState(false);
  const [shared, setShared] = useState(false);

  useEffect(() => {
    if (!shared) return;
    const timer = setTimeout(() => setShared(false), 1600);
    return () => clearTimeout(timer);
  }, [shared]);

  const share = async () => {
    if (!transcript) return;
    // The Web Share sheet where the browser has one, the clipboard everywhere
    // else. Both leave the transcript on the device.
    try {
      if (navigator.share) {
        await navigator.share({ text: transcript });
        return;
      }
      await navigator.clipboard.writeText(transcript);
      setShared(true);
    } catch {
      // A dismissed share sheet and a refused clipboard both land here, and
      // neither is worth interrupting the reader over.
    }
  };

  const choose = (action: () => void) => () => {
    setMenuOpen(false);
    action();
  };

  return (
    <div className={cx("flex shrink-0 items-center gap-0.5", className)}>
      <button
        type="button"
        onClick={share}
        disabled={disabled}
        aria-label={shared ? "Transcript copied" : "Share chat"}
        title={shared ? "Transcript copied" : "Share chat"}
        className={ACTION_BUTTON}
      >
        {shared ? (
          <RiCheckLine className="size-[18px] shrink-0" aria-hidden />
        ) : (
          <RiUploadLine className="size-[18px] shrink-0" aria-hidden />
        )}
      </button>

      <Dropdown isOpen={menuOpen} onOpenChange={setMenuOpen}>
        <DropdownTrigger
          aria-label="More actions for this chat"
          isDisabled={disabled}
          className={cx(ACTION_BUTTON, menuOpen && "bg-background-primary-hover text-text-primary")}
        >
          <RiMoreFill className="size-[18px] shrink-0" aria-hidden />
        </DropdownTrigger>

        <DropdownPopover
          aria-label="More actions for this chat"
          placement="bottom end"
          className="w-[190px] p-2"
        >
          <DropdownGroup>
            <DropdownItem onSelect={choose(onExport)} className="px-2 py-1.5">
              <span className="truncate text-body-medium whitespace-nowrap text-text-primary">
                Export chats
              </span>
            </DropdownItem>
            <DropdownItem onSelect={choose(onToggleUnread)} className="px-2 py-1.5">
              <span className="truncate text-body-medium whitespace-nowrap text-text-primary">
                Mark as unread
              </span>
            </DropdownItem>
            <DropdownItem onSelect={choose(onDelete)} className="px-2 py-1.5">
              <span className="truncate text-body-medium whitespace-nowrap text-text-error-primary">
                Delete chat
              </span>
            </DropdownItem>
          </DropdownGroup>
        </DropdownPopover>
      </Dropdown>
    </div>
  );
}

/** DropdownTrigger is itself a button, so both controls share plain classes
 *  rather than wrapping an IconButton (which would nest one button in another). */
const ACTION_BUTTON = cx(
  "inline-flex size-7 shrink-0 cursor-pointer items-center justify-center rounded-md",
  "text-foreground-icon-secondary transition-colors duration-150 ease",
  "hover:bg-background-primary-hover hover:text-foreground-icon-primary",
  "disabled:cursor-not-allowed disabled:opacity-40",
);

"use client";

import { createContext, useContext, useRef, useState, type ComponentProps, type ReactNode, type RefObject } from "react";
import {
  Button as AriaButton,
  Dialog as AriaDialog,
  DialogTrigger as AriaDialogTrigger,
  Popover as AriaPopover,
} from "react-aria-components";
import {
  MENU_ITEM,
  MENU_ITEM_ACTIVE,
  MENU_ITEM_INTERACTIVE,
  MENU_POPOVER_SURFACE,
  MENU_POPOVER_WIDTH,
} from "@/components/boardui/base/dropdown/menu-styles";
import { cx } from "@/components/boardui/utils/cx";
import { useDismissOnOutsidePress, useTriggerToggle } from "@/components/boardui/utils/use-dismiss-on-outside-press";

/**
 * Dropdown - the BoardUI popover-menu recipe as composable primitives, built
 * on React Aria's DialogTrigger/Popover. Unlike Select (which picks a value
 * into a trigger), Dropdown is a free-form menu surface: grouped rows of
 * actions, headers, footers, whatever the panel needs.
 *
 * The same recipe powers the dashboard sidebar's team/account menus and the
 * AI chat template's add/model/folder menus:
 *
 * - Panel: white, 1px border/button/default, radius 16, p 10, shadow/dropdown.
 * - Appear animation: 150ms fade + scale-95 + 2px blur in and out.
 * - Rows: rounded-2lg, background/secondary/hover on hover and on the selected
 *   row, body-medium labels, 4px apart (the panel's flex column carries a
 *   gap-1, the same rhythm as the Select listbox).
 *
 * Composition:
 *
 * ```tsx
 * <Dropdown isOpen={isOpen} onOpenChange={setIsOpen}>
 *   <DropdownTrigger>Open</DropdownTrigger>
 *   <DropdownPopover aria-label="Actions" placement="bottom start">
 *     <DropdownGroup label="Add">
 *       <DropdownItem onSelect={close}>…row content…</DropdownItem>
 *     </DropdownGroup>
 *     <DropdownDivider />
 *     <DropdownGroup label="Plugins">…</DropdownGroup>
 *   </DropdownPopover>
 * </Dropdown>
 * ```
 *
 * State can be uncontrolled (omit isOpen/onOpenChange) - control it when the
 * trigger needs to react to the open state (e.g. rotating a chevron).
 */

/* ------------------------------------------------------------------- shell */

interface DropdownContextValue {
  triggerRef: RefObject<HTMLButtonElement | null>;
  popoverRef: RefObject<HTMLElement | null>;
}

const DropdownContext = createContext<DropdownContextValue | null>(null);

export interface DropdownProps {
  isOpen?: boolean;
  onOpenChange?: (isOpen: boolean) => void;
  /** Trigger (a DropdownTrigger) followed by a DropdownPopover. */
  children: ReactNode;
}

/**
 * The popover is `isNonModal`: react-aria's modal scroll lock puts
 * `overflow: hidden` on <html>, which collapses the page scroll position and
 * visibly yanks sticky layout (e.g. the docs sidebar) whenever a menu opens.
 * Non-modal skips the lock, but react-aria hard-couples outside-press
 * dismissal to modality - so open state lives here (bridging any controlled
 * props) and dismissal is restored via useDismissOnOutsidePress, the same
 * fix as Select and the date-picker family.
 */
export function Dropdown({ isOpen: controlledOpen, onOpenChange, children }: DropdownProps) {
  const triggerRef = useRef<HTMLButtonElement>(null);
  const popoverRef = useRef<HTMLElement>(null);
  const [uncontrolledOpen, setUncontrolledOpen] = useState(false);

  const isOpen = controlledOpen ?? uncontrolledOpen;
  const setOpen = (next: boolean) => {
    setUncontrolledOpen(next);
    onOpenChange?.(next);
  };

  useDismissOnOutsidePress(isOpen, () => setOpen(false), [triggerRef, popoverRef]);
  // Pressing the trigger while open closes the menu instead of reopening
  const allowOpenChange = useTriggerToggle(isOpen, triggerRef);

  return (
    <DropdownContext.Provider value={{ triggerRef, popoverRef }}>
      <AriaDialogTrigger isOpen={isOpen} onOpenChange={(o) => allowOpenChange(o) && setOpen(o)}>
        {children}
      </AriaDialogTrigger>
    </DropdownContext.Provider>
  );
}

/** The element that opens the menu. Style it entirely via className. */
export function DropdownTrigger({ className, ...props }: ComponentProps<typeof AriaButton>) {
  const context = useContext(DropdownContext);
  return (
    <AriaButton
      ref={context?.triggerRef}
      {...props}
      className={cx(
        "cursor-pointer outline-none focus-visible:ring-2 focus-visible:ring-border-focus-ring",
        className as string,
      )}
    />
  );
}

/* ------------------------------------------------------------------- panel */

export interface DropdownPopoverProps
  extends Pick<ComponentProps<typeof AriaPopover>, "placement" | "offset" | "crossOffset"> {
  "aria-label": string;
  /** Extra classes on the panel - e.g. a width override (default w-[266px]). */
  className?: string;
  /** Classes on the inner dialog (the flex column), e.g. gap between groups. */
  dialogClassName?: string;
  children: ReactNode;
}

export function DropdownPopover({
  "aria-label": ariaLabel,
  placement = "bottom start",
  offset = 4,
  crossOffset,
  className,
  dialogClassName,
  children,
}: DropdownPopoverProps) {
  const context = useContext(DropdownContext);
  return (
    <AriaPopover
      ref={context?.popoverRef}
      isNonModal
      placement={placement}
      offset={offset}
      crossOffset={crossOffset}
      className={cx(
        MENU_POPOVER_WIDTH,
        MENU_POPOVER_SURFACE,
        className,
      )}
    >
      {/* gap-1 keeps bare DropdownItems 4px apart, the same rhythm as the
          Select listbox; DropdownDivider's margins are sized to absorb it. */}
      <AriaDialog aria-label={ariaLabel} className={cx("flex flex-col gap-1 outline-none", dialogClassName)}>
        {children}
      </AriaDialog>
    </AriaPopover>
  );
}

/* ----------------------------------------------------------------- content */

export interface DropdownGroupProps {
  /** Muted body-medium heading above the rows. */
  label?: string;
  className?: string;
  children: ReactNode;
}

export function DropdownGroup({ label, className, children }: DropdownGroupProps) {
  return (
    // pt-1 is spacing for the group LABEL - a label-less group must not
    // carry it, or its first row floats 4px lower than the panel padding
    // implies (visible as extra space above the first item's hover pill).
    <div className={cx("flex w-full flex-col gap-1.5", label && "pt-1", className)}>
      {label && <span className="pl-2 text-body-medium text-text-secondary">{label}</span>}
      <div className="flex w-full flex-col gap-1">{children}</div>
    </div>
  );
}

export interface DropdownItemProps {
  /** Highlights the row like the hover state (current selection). */
  selected?: boolean;
  onSelect?: () => void;
  /** Row padding defaults to p-2 - override for denser rows (px-2 py-1.5). */
  className?: string;
  children: ReactNode;
}

/**
 * A menu row. Content is free-form - icon + label, avatar + name, label +
 * trailing badge - laid out in a gap-2 flex row.
 */
export function DropdownItem({ selected, onSelect, className, children }: DropdownItemProps) {
  return (
    <button
      type="button"
      aria-pressed={selected}
      onClick={onSelect}
      className={cx(
        MENU_ITEM,
        selected ? MENU_ITEM_ACTIVE : MENU_ITEM_INTERACTIVE,
        className,
      )}
    >
      {children}
    </button>
  );
}

/** Full-bleed 1px divider between groups (bleeds through the panel's p-2.5).
 *  my-1.5 + the dialog's gap-1 on both sides = the original 10px breathing room. */
export function DropdownDivider({ className }: { className?: string }) {
  return <div className={cx("-mx-2.5 my-1.5 h-px shrink-0 bg-border-button-default", className)} />;
}

/**
 * Shared visual recipe for BoardUI menu surfaces.
 *
 * Select and Dropdown intentionally keep their distinct React Aria semantics
 * (single-value listbox vs. action menu), while consuming the same panel,
 * motion, and row treatments from here.
 */
export const MENU_POPOVER_SURFACE = [
  "max-w-[calc(100vw-32px)] overflow-y-auto",
  "rounded-2xl border border-border-button-default bg-background-primary-default p-2.5 shadow-dropdown",
  "transition duration-150 ease-out",
